/** Where a visited card sits INSIDE the board, for the camera to dock onto. */
export const boardCard = (slug: string): Rect => {
  const hit = BOARD.cards.find((c) => c.slug === slug);
  if (!hit) throw new Error(`no board rect for ${slug}`);
  return { x: hit.x, y: hit.y, w: hit.w, h: hit.h };
};

/** A board chrome part located by a prefix of its text. */
export const boardPart = (startsWith: string): Part => {
  const part = BOARD.chrome.find((p) => p.text.startsWith(startsWith));
  if (!part) throw new Error(`no board part starting "${startsWith}"`);
  return part;
};

/** The card's one-liner: the longest text node on it, always the reason. */
export const reasonRect = (slug: string): Rect => {
  const card = CARDS.find((c) => c.slug === slug);
  if (!card) throw new Error(`no geometry for ${slug}`);
  const part = [...card.parts].sort((a, b) => b.text.length - a.text.length)[0];
  if (!part) throw new Error(`no text parts on ${slug}`);
  return { x: part.x, y: part.y, w: part.w, h: part.h };
};

/** A detail part located by a prefix of its text. */
export const detailPart = (startsWith: string): Part => {
  const part = DETAIL.parts.find((p) => p.text.startsWith(startsWith));
  if (!part) throw new Error(`no detail part starting "${startsWith}"`);
  return part;
};
